/**
 * Adds the "Send Message to Dayly" Shortcuts action (an App Intent) to the iOS
 * app target.
 *
 * `ios/` is regenerated by `expo prebuild`, so the Swift source lives in
 * plugins/ios/ and this plugin copies it into the app folder and registers it
 * with the main target on every prebuild. App Intents must be compiled into
 * the APP target (not a pod) for Xcode to extract the metadata Shortcuts reads.
 *
 * The intent itself is described in plugins/ios/SendMessageToDaylyIntent.swift.
 */
const fs = require('fs');
const path = require('path');
const { withDangerousMod, withXcodeProject, IOSConfig } = require('expo/config-plugins');

const SWIFT_FILE = 'SendMessageToDaylyIntent.swift';
const SOURCE = path.join(__dirname, 'ios', SWIFT_FILE);

function withSmsAppIntent(config) {
  config = withDangerousMod(config, [
    'ios',
    (cfg) => {
      const projectName = IOSConfig.XcodeUtils.getProjectName(cfg.modRequest.projectRoot);
      const target = path.join(cfg.modRequest.platformProjectRoot, projectName, SWIFT_FILE);
      fs.copyFileSync(SOURCE, target);
      return cfg;
    },
  ]);

  return withXcodeProject(config, (cfg) => {
    const project = cfg.modResults;
    const projectName = IOSConfig.XcodeUtils.getProjectName(cfg.modRequest.projectRoot);
    const filepath = `${projectName}/${SWIFT_FILE}`;
    if (!project.hasFile(filepath)) {
      IOSConfig.XcodeUtils.addBuildSourceFileToGroup({
        filepath,
        groupName: projectName,
        project,
      });
    }
    return cfg;
  });
}

module.exports = withSmsAppIntent;
